 state.put('filterShape',current==null?null:current.length()+':'+current.substring(0,Math.min(3,current.length())));
 List<SelectOption> options=sc.getListViewOptions();List<String> ownedOrder=new List<String>();List<Integer> ownedLengths=new List<Integer>();
 String lowest=null,lowestOwned=null,first=null;Integer currentIndex=-1;
