  if(value!=null && (value.equals(primary) || value.equals(secondary) || value.equals(alphabetical))){ownedOrder.add(value.equals(primary)?'primary':value.equals(secondary)?'secondary':'alphabetical_first');ownedLengths.add(value.length());if(lowestOwned==null || value.compareTo(lowestOwned)<0)lowestOwned=value;}
 }
 state.put('ownedOptionOrder',ownedOrder);state.put('ownedOptionLengths',ownedLengths);state.put('defaultOptionIndex',currentIndex);
 state.put('defaultEqualsFirstOption',current==null?null:current.equals(first));
 state.put('defaultEqualsLowestId',current==null?null:current.equals(lowest));
 state.put('defaultEqualsLowestOwnedId',current==null?null:current.equals(lowestOwned));
 return state;
